<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class AccountVendorController extends Controller {
 private function school(){ $u=auth()->user(); abort_unless($u->status && $u->school_id,403); return $u->school_id; }
 private function table($t){return DB::table($t)->where($t.'.school_id',$this->school());}
 private function vendor($id){$v=$this->table('account_vendors')->where('id',$id)->first();abort_unless($v,404);return $v;}
 private function bills(){return $this->table('account_vendor_invoices')->select('account_vendor_invoices.*')->selectSub($this->table('account_vendor_payments')->whereColumn('invoice_id','account_vendor_invoices.id')->selectRaw('COALESCE(SUM(amount),0)'),'paid');}
 public function index(Request $r){$r->validate(['q'=>'nullable|string|max:100']);$vendors=$this->table('account_vendors')->when($r->filled('q'),fn($q)=>$q->where('name','like','%'.$r->q.'%'))->orderBy('name')->paginate(20)->withQueryString();$bills=$this->bills()->whereIn('status',['approved','partial','paid']);$total=(clone $bills)->sum('amount');$paid=$this->table('account_vendor_payments')->sum('amount');return view('accounts.vendors.index',compact('vendors','total','paid'));}
 private function fields(Request $r){return $r->validate(['name'=>'required|string|max:255','category'=>'required|string|max:100','contact'=>'nullable|string|max:255','phone'=>'nullable|string|max:30','email'=>'nullable|email|max:255','gstin'=>'nullable|alpha_num|size:15','address'=>'nullable|string|max:2000','active'=>'required|boolean']);}
 public function store(Request $r){DB::table('account_vendors')->insert($this->fields($r)+['school_id'=>$this->school(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Vendor added.');}
 public function update(Request $r,$id){$this->vendor($id);$this->table('account_vendors')->where('id',$id)->update($this->fields($r)+['updated_at'=>now()]);return back()->with('success','Vendor updated.');}
 public function ledger(Request $r,$id){$vendor=$this->vendor($id);$years=$this->table('academic_years')->orderByDesc('start_date')->get();$r->validate(['status'=>'nullable|in:pending,approved,partial,paid,rejected']);$bills=$this->bills()->where('vendor_id',$id)->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->orderByDesc('id')->paginate(15)->withQueryString();$payments=$this->table('account_vendor_payments')->join('account_vendor_invoices as i','i.id','=','account_vendor_payments.invoice_id')->where('i.school_id',$this->school())->where('i.vendor_id',$id)->select('account_vendor_payments.*','i.invoice_number')->orderByDesc('account_vendor_payments.id')->paginate(15,['*'],'payments_page')->withQueryString();return view('accounts.vendors.ledger',compact('vendor','years','bills','payments'));}
 public function invoice(Request $r,$id){$vendor=$this->vendor($id);abort_unless($vendor->active,422,'Vendor inactive.');$v=$r->validate(['academic_year_id'=>['required',Rule::exists('academic_years','id')->where('school_id',$this->school())],'invoice_number'=>['required','string','max:100',Rule::unique('account_vendor_invoices')->where('school_id',$this->school())->where('vendor_id',$id)],'invoice_date'=>'required|date_format:Y-m-d|before_or_equal:today','due_date'=>'required|date_format:Y-m-d|after_or_equal:invoice_date','amount'=>'required|numeric|decimal:0,2|min:0.01|max:9999999999.99','description'=>'required|string|max:4000']);$year=$this->table('academic_years')->where('id',$v['academic_year_id'])->first();abort_unless($v['invoice_date'] >= $year->start_date && $v['invoice_date'] <= $year->end_date,422,'Invoice date outside academic year.');DB::table('account_vendor_invoices')->insert($v+['school_id'=>$this->school(),'vendor_id'=>$id,'created_by'=>auth()->id(),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Invoice submitted.');}
 public function review(Request $r,$id){$v=$r->validate(['decision'=>'required|in:approved,rejected','review_note'=>'required_if:decision,rejected|nullable|string|max:2000']);DB::transaction(function()use($v,$id){$b=$this->table('account_vendor_invoices')->where('id',$id)->lockForUpdate()->first();abort_unless($b,404);abort_unless($b->status==='pending' && $b->created_by!=auth()->id(),422,'Another authorized user must review a pending invoice.');$this->table('account_vendor_invoices')->where('id',$id)->update(['status'=>$v['decision'],'review_note'=>$v['review_note']??null,'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Review saved.');}
 private function cents($amount){return (int)round((float)$amount*100);}
 public function pay(Request $r,$id){$v=$r->validate(['amount'=>'required|numeric|decimal:0,2|min:0.01|max:9999999999.99','payment_date'=>'required|date_format:Y-m-d|before_or_equal:today','payment_mode'=>'required|in:cash,upi,bank_transfer,cheque,card,other','reference'=>'required_unless:payment_mode,cash|nullable|string|max:255','request_key'=>'required|uuid']);DB::transaction(function()use($v,$id){$b=$this->table('account_vendor_invoices')->where('id',$id)->lockForUpdate()->first();abort_unless($b,404);$old=$this->table('account_vendor_payments')->where('request_key',$v['request_key'])->first();if($old){abort_unless($old->invoice_id==$id && $this->cents($old->amount)===$this->cents($v['amount']) && $old->payment_date===$v['payment_date'] && $old->payment_mode===$v['payment_mode'] && $old->reference===($v['reference']??null),409,'Payment request already used.');return;}abort_unless(in_array($b->status,['approved','partial']) && $v['payment_date'] >= $b->invoice_date,422,'Invoice must be approved and payment date valid.');$remaining=$this->cents($b->amount)-$this->cents($this->table('account_vendor_payments')->where('invoice_id',$id)->sum('amount'));$amount=$this->cents($v['amount']);abort_unless($amount>0 && $amount<=$remaining,422,'Payment exceeds outstanding balance.');DB::table('account_vendor_payments')->insert($v+['school_id'=>$this->school(),'invoice_id'=>$id,'paid_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);$this->table('account_vendor_invoices')->where('id',$id)->update(['status'=>$amount===$remaining?'paid':'partial','updated_at'=>now()]);});return back()->with('success','Payment recorded.');}
 public function voucher($id){$payment=$this->table('account_vendor_payments')->where('id',$id)->first();abort_unless($payment,404);$bill=$this->table('account_vendor_invoices')->where('id',$payment->invoice_id)->first();abort_unless($bill,404);$vendor=$this->vendor($bill->vendor_id);return view('accounts.vendors.voucher',compact('payment','bill','vendor'));}
}
